#include "rx.h"
using namespace std;int main(){vector<int>a[304];for(int i=0;i<304;i++){if(i%19)a[i].push_back(i-1);if(i%19<18)a[i].push_back(i+1);if(i>=19)a[i].push_back(i-19);if(i+19<304)a[i].push_back(i+19);}ifstream in(S("thFile"));if(!in){cerr<<"нет файла "<<S("thFile")<<" (сначала запустите сводку)\n";return 2;}long long ticks=PI("thTicks"),expT=PI("thExp");ofstream out("thermal-check.csv");out<<"layout,lost_outlets,nef_expires,ticks,max_coolant,max_hull,max_vent_before_drain,max_vent_after_drain,steady_power,final_power,result\n";string name,original;int pr,dl,nl,ff;while(in>>name>>pr>>dl>>nl>>ff>>original)for(int lost:{0,1})for(int expires:{0,1}){string g=original;int k=count(g.begin(),g.end(),'K'),v=count(g.begin(),g.end(),'V')-4*lost,pc=count(g.begin(),g.end(),'P');double rate=EM.rate*(1+EM.rateK*k),vent=EM.vent*(pr?8:7)*(1+(pr==2?.35:.30)*k),vcap=EM.vcap*(pr?8:7)*(1+(pr?.30:.25)*pc),hcap=EM.hull*pc;array<double,304>load{},ch{};array<int,304>ins{};double direct=0,base=0;auto core=[](char c){return c=='F'?4:c=='1'?1:c=='2'?2:c=='4'?4:0;};auto calculate=[&](){load.fill(0);direct=base=0;for(int i=0;i<304;i++){ins[i]=0;for(int j:a[i])ins[i]+=g[j]=='I';int c=core(g[i]);if(!c)continue;int pulse=c==1?1:c==2?4:12,r=0,cs=0;for(int j:a[i]){pulse+=core(g[j]);r+=g[j]=='R';cs+=g[j]=='C';}double h=pulse*pulse*(g[i]=='F'?EM.FH:EM.NH)/c;base+=pulse*(g[i]=='F'?EM.FP*(1+.5*dl):EM.NH*(1+nl))*(1+EM.refl*r);if(cs)for(int j:a[i])if(g[j]=='C')load[j]+=h/cs;if(!cs)direct+=h;}};calculate();double hull=0,vh=0,maxc=0,maxh=0,maxv=0,maxva=0,power=0,steady=0;string result="PASS";long long t;for(t=1;t<=ticks;t++){if(expires&&t==expT){for(char &c:g)if(c=='1'||c=='2'||c=='4')c='x';calculate();}power=base*(hull>1e-6?1+.01*(5+ff)*log(hull*1e9)/log(1000.):1);if(t==1000)steady=power;hull+=direct;for(int i=0;i<304;i++){ch[i]+=load[i];maxc=max(maxc,ch[i]);}maxh=max(maxh,hull);double flow=min(hull,v*rate);hull-=flow;vh+=flow/v;maxv=max(maxv,vh);vh=max(0.,vh-vent);maxva=max(maxva,vh);for(int i=0;i<304;i++){double move=min(ch[i],ins[i]*rate);ch[i]-=move;hull+=move;if(ch[i]>=EM.ccap)result="COOLANT_FAIL";}maxh=max(maxh,hull);if(vh>=vcap)result="VENT_FAIL";if(hull>=hcap)result="HULL_FAIL";hull=max(0.,hull-hcap*.0001);if(result!="PASS")break;}out<<name<<","<<lost<<","<<expires<<","<<min(t,ticks)<<","<<maxc<<","<<maxh<<","<<maxv<<","<<maxva<<","<<steady<<","<<power<<","<<result<<"\n";cout<<name<<" потеря выхода "<<lost<<" истечение "<<expires<<": "<<result<<"\n";}return 0;}
